<?php
require_once '../../config/auth.php'; require_once '../../config/database.php'; requireOsisMember();
$q=$pdo->prepare("SELECT om.id,s.nama_lengkap FROM osis_members om JOIN students s ON s.id=om.student_id JOIN academic_years ay ON ay.id=om.academic_year_id WHERE s.user_id=? AND om.status='aktif' AND ay.status='aktif' LIMIT 1");$q->execute([$_SESSION['user_id']]);$member=$q->fetch(PDO::FETCH_ASSOC)?:['id'=>0,'nama_lengkap'=>'Anggota OSIS'];
$q=$pdo->prepare("SELECT a.*,ac.jabatan_panitia FROM activities a LEFT JOIN activity_committees ac ON ac.activity_id=a.id AND ac.osis_member_id=? ORDER BY CASE a.status WHEN 'berlangsung' THEN 0 WHEN 'rencana' THEN 1 ELSE 2 END,a.tanggal_mulai DESC");$q->execute([$member['id']]);$activities=$q->fetchAll(PDO::FETCH_ASSOC);$pageTitle='Agenda Kegiatan OSIS';require_once '../../includes/header.php';require_once '../../includes/osis_sidebar.php';?>
<div class="osis-main-content"><header class="osis-topbar"><button class="btn btn-light d-lg-none" id="osisMenuToggle"><i class="bi bi-list"></i></button><div><strong>Agenda Kegiatan</strong><small class="d-block text-muted">Jadwal kegiatan OSIS</small></div></header><main class="role-page member-home-page"><div class="role-wrap member-home-wrap"><section class="member-home-hero member-subhero"><div><span class="member-home-kicker"><i class="bi bi-calendar-event"></i> Kalender organisasi</span><h1>Agenda OSIS</h1><p>Ketahui jadwal kegiatan dan peran kepanitiaan Anda lebih awal.</p></div></section><section class="member-home-card member-agenda-card"><div class="member-agenda-list member-agenda-full"><?php foreach($activities as $a): ?><div><time><b><?=date('d',strtotime($a['tanggal_mulai']))?></b><small><?=strtoupper(date('M',strtotime($a['tanggal_mulai'])))?></small></time><p><strong><?=htmlspecialchars($a['nama_kegiatan'])?></strong><span><i class="bi bi-clock"></i> <?=date('d M Y, H:i',strtotime($a['tanggal_mulai']))?> WIB · <i class="bi bi-geo-alt"></i> <?=htmlspecialchars($a['lokasi']?:'Lokasi menyusul')?></span><?php if($a['deskripsi']):?><small><?=htmlspecialchars(mb_strimwidth($a['deskripsi'],0,180,'…'))?></small><?php endif;?><?php if($a['jabatan_panitia']):?><em><i class="bi bi-person-workspace"></i> Peran Anda: <?=htmlspecialchars($a['jabatan_panitia'])?></em><?php endif;?></p><label class="<?=htmlspecialchars($a['status'])?>"><?=htmlspecialchars(ucfirst($a['status']))?></label></div><?php endforeach;if(!$activities):?><aside class="member-empty"><i class="bi bi-calendar-x"></i><strong>Belum ada kegiatan</strong><span>Agenda baru akan tampil di halaman ini.</span></aside><?php endif;?></div></section></div></main></div><?php require_once '../../includes/footer.php';?>
